mapper.select:
SELECT 
FROM alphafrog_agent_async_tool_task
WHERE run_id = #{runId}
  AND work_item_id IS NOT DISTINCT FROM #{workItemId}
  AND tool_name = #{toolName}
  AND state = 'FAILED'
ORDER BY job_id DESC
LIMIT #{limit}

SELECT 
FROM alphafrog_agent_async_tool_task
WHERE state IN ('PENDING', 'RUNNING')
  AND next_poll_at IS NOT NULL
  AND next_poll_at <= #{now}
  AND (lease_expires_at IS NULL OR lease_expires_at <= #{now})
  AND job_id > #{afterJobId}
ORDER BY job_id
LIMIT #{limit}

mapper.update:
UPDATE alphafrog_agent_async_tool_task
SET next_poll_at = #{nextPollAt},
    poll_count = #{pollCount},
    lease_expires_at = #{leaseUntil},
    updated_at = CURRENT_TIMESTAMP
WHERE job_id = #{jobId}
  AND owner_instance_id = #{owner}
  AND claim_epoch = #{claimEpoch}
  AND state = 'RUNNING'

UPDATE alphafrog_agent_async_tool_task
SET state = #{state},
    result_ref_json = #{resultRefJson}::jsonb,
    finished_at = #{finishedAt},
    next_poll_at = NULL,
    updated_at = CURRENT_TIMESTAMP
WHERE job_id = #{jobId}
  AND owner_instance_id = #{owner}
  AND claim_epoch = #{claimEpoch}
  AND state IN ('PENDING', 'RUNNING')

mapper.select:
SELECT FROM alphafrog_agent_async_tool_task WHERE stop_state IN ('PENDING', 'CLAIMED') -- 到期时刻为空视为立刻到期：停机意图不允许因为少写一个时刻而永远扫不到。 AND (next_poll_at IS NULL OR next_poll_at <= #{now}) AND (lease_expires_at IS NULL OR lease_expires_at <= #{now}) AND job_id > #{afterJobId} -- 只取本部署代际、本泳道的待停任务。这里必须与旧停机表扫描 -- （WaitMemberStopMapper.claimDue）一样带部署标识与部署代际：蓝绿另一组实例 -- 领走后归属检查返回空，重试用尽会把 stop_state 写成已确认，真正归属的实例 -- 再也停不掉那个沙箱作业。部署代际在第二步切换归属判据时随 findOwnedRun -- 一起去掉，不能提前单独去掉。泳道按现有约定匹配：进程泳道为空时只取空值。 AND EXISTS ( SELECT 1 FROM alphafrog_agent_run r WHERE r.id = alphafrog_agent_async_tool_task.run_id AND r.deployment_id = #{deploymentId} AND r.deployment_generation_id = #{deploymentGenerationId} AND
r.lane_tag IS NULL
r.lane_tag = #{laneTag}
) ORDER BY job_id LIMIT #{limit}

mapper.update:
UPDATE alphafrog_agent_async_tool_task
SET stop_state = 'CONFIRMED',
    stop_last_error = #{reason},
    updated_at = CURRENT_TIMESTAMP
WHERE job_id = #{jobId}
  AND owner_instance_id = #{owner}
  AND claim_epoch = #{claimEpoch}
  AND stop_state = 'CLAIMED'
